using System;

public abstract class FeeCalculator
{
    public abstract decimal CalculateFee(decimal transactionAmount);
}

public sealed class FixedFeeCalculator : FeeCalculator
{
    private const decimal FlatFee = 5000m;

    public override decimal CalculateFee(decimal transactionAmount)
    {
        if (transactionAmount <= 0) return 0m;
        return FlatFee;
    }
}

public sealed class PercentageFeeCalculator : FeeCalculator
{
    private readonly decimal _percentage;

    public PercentageFeeCalculator(decimal percentage)
    {
        _percentage = percentage;
    }

    public override decimal CalculateFee(decimal transactionAmount)
    {
        if (transactionAmount <= 0) return 0m;
        return transactionAmount * (_percentage / 100m);
    }
}

public class Program
{
    public static void Main()
    {
        FeeCalculator f1 = new FixedFeeCalculator();
        FeeCalculator f2 = new PercentageFeeCalculator(2.5m);

        Console.WriteLine($"Fixed: Rp {f1.CalculateFee(100000m):N0}");
        Console.WriteLine($"Percent: Rp {f2.CalculateFee(100000m):N0}");
    }
}
